// Responsive project screenshot: AVIF and WebP srcsets with a JPEG fallback.
// width/height reserve the box so the image never causes layout shift.
// Variants are generated by scripts/make-variants.mjs.
const ProjectImage = ({ image, alt, sizes, className, eager = false }) => {
  const { name, widths, width, height, avif } = image;
  const largest = Math.max(...widths);
  const srcSet = (ext) => widths.map((w) => `/img/${name}-${w}.${ext} ${w}w`).join(', ');
  return (
    <picture>
      {avif && <source type="image/avif" srcSet={srcSet('avif')} sizes={sizes} />}
      <source type="image/webp" srcSet={srcSet('webp')} sizes={sizes} />
      <img
        src={`/img/${name}-${largest}.jpg`}
        alt={alt}
        width={width}
        height={height}
        className={className}
        loading={eager ? 'eager' : 'lazy'}
        decoding="async"
      />
    </picture>
  );
};

export default ProjectImage;
